import sys
from collections import deque

def bfs(start, end, dictionary):
    queue = deque([(start, 0)])
    visited = set([start])

    while queue:
        current, steps = queue.popleft()

        if current == end:
            return steps

        for word in dictionary:
            if word not in visited and sum(c != d for c, d in zip(current, word)) == 1:
                visited.add(word)
                queue.append((word, steps + 1))

    return -1

def find_best_word_to_add(dictionary):
    start = dictionary[0]
    end = dictionary[1]

    # Check if we can reach the end without adding any word
    steps_without_addition = bfs(start, end, dictionary[2:])
    if steps_without_addition != -1:
        return "0", steps_without_addition

    best_word = None
    min_steps = float('inf')

    for i in range(2, len(dictionary)):
        temp_dict = dictionary[:i] + dictionary[i+1:]
        steps = bfs(start, end, temp_dict)

        if steps != -1 and steps < min_steps:
            min_steps = steps
            best_word = dictionary[i]
        elif steps != -1 and steps == min_steps:
            best_word = min(best_word, dictionary[i])

    if best_word is None:
        return "0", -1
    else:
        return best_word, min_steps

